/** The prototype of each printable ASCII character that has one. */
export const ASCII_SKELETON: Readonly<Record<string, string>> = {"\"": "''", "0": "O", "1": "l", "I": "l", "`": "'", "m": "rn", "|": "l"};

/** The twelve Bidi_Control code points. */
export const BIDI_CONTROLS: readonly number[] = [0x061C, 0x200E, 0x200F, 0x202A, 0x202B, 0x202C, 0x202D, 0x202E, 0x2066, 0x2067, 0x2068, 0x2069];

/** The prototype table, built on first use. */
let table: Map<number, string> | null = null;

/** The ASCII prototype a code point outside ASCII is confusable with, if any. */
export function asciiPrototype(cp: number): string | undefined {
  // Build once.
  if (!table) {
    // The map.
    const m = new Map<number, string>();
    // Each entry: code point, colon, prototype.
    for (const e of PROTO_TEXT.split("\u0001")) { const k = e.indexOf(":"); m.set(parseInt(e.slice(0, k), 16), e.slice(k + 1)); }
    // Keep it.
    table = m;
  }
  // Look it up.
  return table.get(cp);
}

/** Every printable ASCII character whose own prototype is the given one (the character itself counts). */
export function asciiSharing(prototype: string): string[] {
  // The matches.
  const out: string[] = [];
  // Printable ASCII, 33 to 126.
  for (let c = 33; c <= 126; c++) { const ch = String.fromCharCode(c); if ((ASCII_SKELETON[ch] ?? ch) === prototype) out.push(ch); }
  // Done.
  return out;
}

/** True for a Bidi_Control character. */
export function isBidiControl(cp: number): boolean {
  // Twelve values.
  return BIDI_CONTROLS.includes(cp);
}
